{"file_path":"src/env.js","content":"/** The environment layer: `CONF_*` variables read as lines from standard input. */

import { indent, valuePosition } from './ini.js'
import { SETTINGS } from './schema.js'

/** One refusal of an environment line, carrying the 1-based line and column it was read at. */
export class EnvError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'EnvError'
    this.line = line
    this.column = column
  }
}

const NAME_BY_KEY = new Map(SETTINGS.map(declared => [declared.key, `CONF_${declared.key.toUpperCase().replace(/\./gu, '_')}`]))
const KEY_BY_NAME = new Map([...NAME_BY_KEY].map(([key, name]) => [name, key]))

/**
 * Parse environment text into its settings.
 * @param {string} text - standard input's whole text.
 * @returns {{values: Map<string, string>, positions: Map<string, {line: number, column: number}>}}
 *   each schema key's raw value, in the order the input writes them, and the position its value
 *   was written at.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  const positions = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, indent(raw), 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, indent(raw), 'expected a variable name')
    const key = KEY_BY_NAME.get(name)
    if (key === undefined) throw new EnvError(line, indent(raw), `unknown environment variable ${name}`)
    if (values.has(key)) throw new EnvError(line, indent(raw), `${name} is set twice`)
    values.set(key, trimmed.slice(split + 1).trim())
    positions.set(key, { line, column: valuePosition(raw, trimmed, split) })
  }
  return { values, positions }
}
"}

