{"file_path":"src/layer.js","content":"/** Stacking layers: the last layer that sets a key wins. */

/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, file: string, values: Map<string, string>, positions?: Map<string, {line: number, column: number}>}[]} layers -
 *   the layers, weakest first.
 * @returns {{values: Map<string, string>, origin: Map<string, {layer: string, file: string, line: number, column: number}>}}
 *   each key's winning raw text, and which layer (and position) set it.
 */
export function merge(layers) {
  const values = new Map()
  const origin = new Map()
  for (const layer of layers) {
    for (const [key, text] of layer.values) {
      values.set(key, text)
      const position = layer.positions ? layer.positions.get(key) : undefined
      origin.set(key, { layer: layer.name, file: layer.file, line: position?.line, column: position?.column })
    }
  }
  return { values, origin }
}
"}

