{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { parse as parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { coerce, SETTINGS, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    const { values, positions } = parseIni(readFileSync(path, 'utf8'))
    return { name, file: path, values, positions }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/** An INI layer, additionally refusing any key the schema does not know, in the file's own order. */
function strictIniLayer(name, path) {
  const layer = iniLayer(name, path)
  for (const key of layer.values.keys()) {
    if (setting(key) === undefined) {
      const position = layer.positions.get(key)
      fail(`${path}:${position.line}:${position.column}: unknown setting ${key}`)
    }
  }
  return layer
}

/** The environment layer, read from standard input. */
function envLayer() {
  const text = readFileSync(0, 'utf8')
  try {
    const { values, positions } = parseEnv(text)
    return { name: 'env', file: '<stdin>', values, positions }
  } catch (error) {
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
}

/** The winning text, file and position for one schema key, or its default with no position. */
function resolve(merged, key) {
  if (merged.origin.has(key)) {
    const origin = merged.origin.get(key)
    return { text: merged.values.get(key), file: origin.file, line: origin.line, column: origin.column }
  }
  return { text: setting(key).default, file: undefined, line: undefined, column: undefined }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []
if (mode === 'dump' || mode === 'get') {
  const merged = merge([iniLayer('file', argv[1])])
  const raw = key => (merged.values.has(key) ? merged.values.get(key) : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const base = strictIniLayer('base', argv[1])
  const site = strictIniLayer('site', argv[2])
  const env = envLayer()
  const merged = merge([base, site, env])
  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const layer = merged.origin.has(declared.key) ? merged.origin.get(declared.key).layer : 'default'
      out.push(`${declared.key} ${layer}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const { text, file, line, column } = resolve(merged, declared.key)
      const result = coerce(declared, text)
      if (!result.ok) {
        const where = file === undefined ? '' : `${file}:${line}:${column}`
        fail(`${where}: ${result.message}`)
      }
      out.push(`${declared.key}=${result.value}`)
    }
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

